"""SCMOVS update: popups (modals) for New/Edit Election, Position, Council, Event, Project, Budget and Expense.

HOW TO USE
  1. Put this file in your project folder (the folder that contains run.py).
  2. In PowerShell, inside that folder, run:   python apply_update.py
  3. Restart the app (python run.py) and press Ctrl+F5 in the browser.

It writes 25 files. Before replacing a file it saves your current copy in the folder  _update_backup/
(same sub-folders), so you can undo by copying those files back. Nothing else is touched.
"""
import base64
import os
import shutil
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))

FILES = {
    'app/councils/routes.py': "",
    'app/elections/routes.py': "",
    'app/finance/routes.py': "",
    'app/modal_utils.py': "",
    'app/positions/routes.py': "",
    'app/proposals/routes.py': "",
    'static/js/modal.js': "",
    'templates/components/_notice.html': "",
    'templates/components/modal.html': "",
    'templates/councils/_form_modal.html': "",
    'templates/councils/detail.html': "",
    'templates/councils/list.html': "",
    'templates/elections/_form_modal.html': "",
    'templates/elections/detail.html': "",
    'templates/elections/list.html': "",
    'templates/finance/_form_modal.html': "",
    'templates/finance/detail.html': "",
    'templates/finance/list.html': "",
    'templates/positions/_form_modal.html': "",
    'templates/positions/list.html': "",
    'templates/proposals/_form_modal.html': "",
    'templates/proposals/detail.html': "",
    'templates/proposals/list.html': "",
    'tests/run_all.sh': "",
    'tests/test_modals_more.py': "",
}


def main():
    if not os.path.isfile(os.path.join(ROOT, "run.py")) or not os.path.isdir(os.path.join(ROOT, "app")):
        print("STOP: put apply_update.py in your project folder (the one that has run.py and the app folder), then run it again.")
        sys.exit(1)
    backup_root = os.path.join(ROOT, "_update_backup")
    written = 0
    for rel, encoded in FILES.items():
        target = os.path.join(ROOT, *rel.split("/"))
        if os.path.isfile(target):
            saved = os.path.join(backup_root, *rel.split("/"))
            os.makedirs(os.path.dirname(saved), exist_ok=True)
            if not os.path.exists(saved):          # keep the ORIGINAL if the script is run twice
                shutil.copy2(target, saved)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as handle:
            handle.write(base64.b64decode(encoded))
        written += 1
        print("  updated", rel)
    print(f"\nDone: {written} files written. Your previous copies are in _update_backup/.")
    print("Next: restart the app (python run.py) and press Ctrl+F5 in the browser.")


if __name__ == "__main__":
    main()
